def check_solution(i, j):
    # Core equation: 2^i * 5^j + 2 * 5^2 = 2^k * 5^l
    LHS = (2**i) * (5**j) + 2 * 25

    # Check if LHS is of the form 2^k * 5^l
    # Factor out all powers of 2 and 5

    if LHS <= 0:
        return None

    count2 = 0
    temp = LHS
    while temp > 0 and temp % 2 == 0:
        count2 += 1
        temp //= 2

    count5 = 0
    while temp > 0 and temp % 5 == 0:
        count5 += 1
        temp //= 5

    # If temp is 1, LHS is of the required form 2^k * 5^l
    if temp == 1:
        # We found a potential (a, b) pair: a = count2, b = count5
        return (count2, count5)
    else:
        return None

solutions = set()
# Investigate i and j up to 8 to find structural solutions
for i in range(9):
    for j in range(9):
        sol = check_solution(i, j)
        if sol:
            solutions.add(sol)

print(f"Solutions (a, b) found for small exponents: {solutions}")
